SOURCE_FILE = '数字货币期货类马丁策略.md'
SOURCE_FEATURES = ['var ', 'for ', 'while ', 'exchange.', '_C(', 'Sleep(', 'GetTicker', 'GetAccount']
SOURCE_FIDELITY_NOTES = ['FMZ JavaScript is event/API driven. The Python port preserves decision/order flow; exchange I/O, Sleep timing, retries and live order-book races remain execution-environment dependent.', 'Uses ticker/depth data; OHLCV-only backtests cannot reproduce microstructure fills exactly.']
ORIGINAL_JAVASCRIPT = '// OKEX V5 获取总权益\nfunction getTotalEquity_OKEX_V5() {\n    var totalEquity = null \n    var ret = exchange.IO("api", "GET", "/api/v5/account/balance", "ccy=USDT")\n    if (ret) {\n        try {\n            totalEquity = parseFloat(ret.data[0].details[0].eq)\n        } catch(e) {\n            Log("获取账户总权益失败！")\n            return null\n        }\n    }\n    return totalEquity\n}\n\n// 币安期货\nfunction getTotalEquity_Binance() {\n    var totalEquity = null \n    var ret = exchange.GetAccount()\n    if (ret) {\n        try {\n            totalEquity = parseFloat(ret.Info.totalWalletBalance)\n        } catch(e) {\n            Log("获取账户总权益失败！")\n            return null\n        }\n    }\n    return totalEquity\n}\n\n// dYdX\nfunction getTotalEquity_dYdX() {\n    var totalEquity = null \n    var ret = exchange.GetAccount()\n    if (ret) {\n        totalEquity = ret.Balance\n    }\n    return totalEquity\n}\n\n// BitMEX\nfunction getTotalEquity_BitMEX() {\n    var currency = exchange.GetCurrency()\n    var arr = currency.split("_")\n    if (arr.length != 2) {\n        throw "交易对配置错误"\n    }\n    var baseCurrency = arr[0]\n    var quoteCurrency = arr[1]\n    var coinName = ""\n    var scale = 0.0\n    if (quoteCurrency == "USDT") {\n        coinName = "USDt"\n        scale = 6\n    } else if (quoteCurrency == "USD") {\n        coinName = "XBt"\n        scale = 8\n    } else {\n        throw "不支持"\n    }\n\n    var ret = exchange.IO("api", "GET", "/api/v1/user/margin", "currency=all")\n    if (ret) {\n        for (var i = 0 ; i < ret.length ; i++) {\n            if (coinName == ret[i].currency) {\n                var equity = ret[i]["marginBalance"]\n                if (equity) {\n                    return parseFloat(equity) / Math.pow(10, scale)\n                }                \n            }\n        }\n    } else {\n        Log("获取账户总权益失败！")\n        return null \n    }\n}\n\nfunction getTotalEquity() {\n    var exName = exchange.GetName()\n    if (exName == "Futures_OKCoin") {\n        return getTotalEquity_OKEX_V5()\n    } else if (exName == "Futures_Binance") {\n        return getTotalEquity_Binance()\n    } else if (exName == "Futures_dYdX") {\n        return getTotalEquity_dYdX()\n    } else if (exName == "Futures_BitMEX") {\n        return getTotalEquity_BitMEX()\n    } else {\n        throw "不支持该交易所"\n    }\n}\n\nfunction cancelAll() {\n    while (1) {\n        var orders = _C(exchange.GetOrders)\n        if (orders.length == 0) {\n            break\n        }\n        for (var i = 0 ; i < orders.length ; i++) {\n            exchange.CancelOrder(orders[i].Id, orders[i])\n            Sleep(500)\n        }\n        Sleep(500)\n    }\n}\n\nfunction trade(distance, price, amount) {\n    var tradeFunc = null \n    if (distance == "buy") {\n        tradeFunc = exchange.Buy\n    } else if (distance == "sell") {\n        tradeFunc = exchange.Sell\n    } else if (distance == "closebuy") {\n        tradeFunc = exchange.Sell\n    } else {\n        tradeFunc = exchange.Buy\n    }\n    exchange.SetDirection(distance)\n    return tradeFunc(price, amount)\n}\n\nfunction openLong(price, amount) {\n    return trade("buy", price, amount)\n}\n\nfunction openShort(price, amount) {\n    return trade("sell", price, amount)\n}\n\nfunction coverLong(price, amount) {\n    return trade("closebuy", price, amount)\n}\n\nfunction coverShort(price, amount) {\n    return trade("closesell", price, amount)\n}\n\nvar buyOrderId = null\nvar sellOrderId = null\nvar chartUpdateTS = 0 \n\nfunction riskControl() {\n    var ts = new Date().getTime()\n    var data = _G("riskControData")\n    if (!data) {\n        // 没有风控数据，初始化\n        data = {timeStamp : ts, tradeTimes : 0}\n        _G("riskControData", data)\n    }\n    \n    if (ts - data.timeStamp > 1000 * 60 * 60 * 24) {\n        data.tradeTimes = 0 \n        data.timeStamp = ts\n        Log("风控模块重置时间：", data)\n    }\n    data.tradeTimes++\n    _G("riskControData", data)\n    \n    if (data.tradeTimes > 10) {\n        Log("触发风控：", data)\n        return false \n    }\n    return true \n}\n\nfunction main() {\n    var exName = exchange.GetName()    \n    // 切换OKEX V5模拟盘\n    if (isSimulate && exName == "Futures_OKCoin") {\n        exchange.IO("simulate", true)\n    }\n\n    if (isReset) {\n        _G(null)\n        LogReset(1)\n        LogProfitReset()\n        LogVacuum()\n        Log("重置所有数据", "#FF0000")\n    }\n\n    Log("当前模式：", ["双向", "只做多", "只做空"][mode])\n\n    exchange.SetContractType("swap")\n    exchange.SetPrecision(pricePrecision, amountPrecision)\n    Log("设置精度", pricePrecision, amountPrecision)\n\n    if (totalEq == -1 && !IsVirtual()) {\n        var recoverTotalEq = _G("totalEq")\n        if (!recoverTotalEq) {\n            var currTotalEq = getTotalEquity()\n            if (currTotalEq) {\n                totalEq = currTotalEq\n                _G("totalEq", currTotalEq)\n            } else {\n                throw "获取初始权益失败"\n            }\n        } else {\n            totalEq = recoverTotalEq\n        }\n    }\n\n    var n = 1   // 加仓系数\n    while (1) {\n        // 风控\n        /*\n        if (!riskControl()) {\n            Sleep(1000 * 60 * 30)\n            continue\n        }\n        */\n        \n        var ticker = _C(exchange.GetTicker)\n        var pos = _C(exchange.GetPosition)\n        if (pos.length > 1) {\n            Log(pos)\n            throw "同时有多空持仓"\n        }\n        // 根据状态而定\n        if (pos.length == 0) {\n            // 未持仓了，统计一次收益\n            if (!IsVirtual()) {\n                var currTotalEq = getTotalEquity()\n                if (currTotalEq) {\n                    LogProfit(currTotalEq - totalEq, "当前总权益：", currTotalEq)\n                }\n            }\n            \n            if (mode == 0) {\n                buyOrderId = openLong(ticker.Last - targetProfit, amount)\n                sellOrderId = openShort(ticker.Last + targetProfit, amount)\n            } else if (mode == 1) {\n                buyOrderId = openLong(ticker.Last - targetProfit, amount)\n            } else if (mode == 2) {\n                sellOrderId = openShort(ticker.Last + targetProfit, amount)\n            }\n            n = 1    // 初始为1\n        } else if (pos[0].Type == PD_LONG) {   // 有多头持仓\n            n += increment\n            var price = ticker.Last\n            buyOrderId = openLong(price - targetProfit * n, amount)\n            sellOrderId = coverLong(pos[0].Price + targetProfit, pos[0].Amount)\n        } else if (pos[0].Type == PD_SHORT) {   // 有空头持仓\n            n += increment\n            var price = ticker.Last\n            buyOrderId = coverShort(pos[0].Price - targetProfit, pos[0].Amount)\n            sellOrderId = openShort(price + targetProfit * n, amount)\n        }\n\n        if (mode == 0 && (!sellOrderId || !buyOrderId)) {\n            cancelAll()\n            buyOrderId = null \n            sellOrderId = null\n            continue\n        } else if (mode == 1 && pos.length == 0 && !buyOrderId) {\n            cancelAll()\n            buyOrderId = null \n            sellOrderId = null\n            continue\n        } else if (mode == 2 && pos.length == 0 && !sellOrderId) {\n            cancelAll()\n            buyOrderId = null \n            sellOrderId = null\n            continue\n        } else if (pos.length != 0 && (!sellOrderId || !buyOrderId)) {\n            cancelAll()\n            buyOrderId = null \n            sellOrderId = null\n            continue\n        }\n\n        while (1) {  // 监控订单\n            var isFindBuyId = false \n            var isFindSellId = false\n            var buyOrder = null \n            var sellOrder = null \n            var orders = _C(exchange.GetOrders)\n            var t = exchange.GetTicker()\n            for (var i = 0 ; i < orders.length ; i++) {\n                if (buyOrderId == orders[i].Id) {\n                    isFindBuyId = true \n                    buyOrder = orders[i]\n                }\n                if (sellOrderId == orders[i].Id) {\n                    isFindSellId = true \n                    sellOrder = orders[i]\n                }               \n            }\n            if (!isFindSellId && !isFindBuyId) {    // 买卖单都成交了\n                cancelAll()\n                break\n            } else if (!isFindBuyId && (mode == 0 || (mode == 2 && pos.length != 0))) {   // 买单成交\n                // 双向模式，只做空模式有持仓，找不到买单时\n                Log("买单成交")\n                cancelAll()\n                break\n            } else if (!isFindSellId && (mode == 0 || (mode == 1 && pos.length != 0))) {  // 卖单成交\n                // 双向模式，只做多模式有持仓，找不到卖单时\n                Log("卖单成交")\n                cancelAll()\n                break\n            } else if (mode == 1 && pos.length == 0 && isFindBuyId && t && buyOrder && t.Last - buyOrder.Price > maxPendingDiff) {\n                // 只做多模式，没有持仓，查询到买单存在，订单价格超出\n                Log("当前价格超出最大距离，撤销买单订单！当前价格：", t.Last, "订单价格：", buyOrder.Price, "最大距离：", maxPendingDiff)\n                cancelAll()\n                break\n            } else if (mode == 2 && pos.length == 0 && isFindSellId && t && sellOrder && sellOrder.Price - t.Last > maxPendingDiff) {\n                // 只做空模式，没有持仓，查询到卖单存在，订单价格超出\n                Log("当前价格超出最大距离，撤销卖单订单！当前价格：", t.Last, "订单价格：", buyOrder.Price, "最大距离：", maxPendingDiff)\n                cancelAll()\n                break\n            } else if (!isFindBuyId && pos.length != 0) {\n                // 有持仓，找不到买单时，条件可以合并\n                Log("买单成交")\n                cancelAll()\n                break\n            } else if (!isFindSellId && pos.length != 0) {\n                // 有持仓，找不到卖单时\n                Log("卖单成交")\n                cancelAll()\n                break\n            }\n            \n            if (!IsVirtual()) {\n                var currTotalEq = getTotalEquity()\n                var pos = exchange.GetPosition()\n                if (currTotalEq && pos) {\n                    // LogStatus(_D(), "当前总权益：", currTotalEq, "持仓：", pos)\n                    var tblPos = {\n                        "type" : "table",\n                        "title" : "持仓",\n                        "cols" : ["持仓数量", "持仓方向", "持仓均价", "持仓盈亏", "合约代码", "自定义字段 / " + SpecifyPosField],\n                        "rows" : []\n                    }\n                    var descType = ["多头仓位", "空头仓位"]\n                    for (var posIndex = 0 ; posIndex < pos.length ; posIndex++) {\n                        tblPos.rows.push([pos[posIndex].Amount, descType[pos[posIndex].Type], pos[posIndex].Price, pos[posIndex].Profit, pos[posIndex].ContractType, SpecifyPosField == "" ? "--" : pos[posIndex].Info[SpecifyPosField]])\n                    }\n                    \n                    var tbl = {\n                        "type" : "table",\n                        "title" : "数据",\n                        "cols" : ["当前总权益", "实际盈亏", "当前价格", "买单价格/数量", "卖单价格/数量"],\n                        "rows" : []\n                    }\n                    \n                    /*\n                    var buyOrder = null \n                    var sellOrder = null \n                    for (var orderIndex = 0 ; orderIndex < orders.length ; orderIndex++) {\n                        if (orders[orderIndex].Type == ORDER_TYPE_BUY) {\n                            buyOrder = orders[orderIndex]\n                        } else {\n                            sellOrder = orders[orderIndex]\n                        }\n                    }\n                    */\n                    var realProfit = currTotalEq - totalEq\n                    if (exchange.GetName() == "Futures_Binance") {\n                        _.each(pos, function(p) {\n                            realProfit += parseFloat(p.Info.unRealizedProfit)\n                        })                        \n                    }\n                    // var t = exchange.GetTicker()\n                    tbl.rows.push([currTotalEq, realProfit, t ? t.Last : "--", buyOrder ? (buyOrder.Price + "/" + buyOrder.Amount) : "--/--", sellOrder ? (sellOrder.Price + "/" + sellOrder.Amount) : "--/--"])\n                    \n                    // 更新图表数据             \n                    if (t && showLine) {\n                        var ts = new Date().getTime()\n                        if (ts - chartUpdateTS > 60 * 1000 * 5) {\n                            chartUpdateTS = ts \n                            $.PlotLine("当前价格", t.Last)\n                        }\n                    }\n                    \n                    // 更新状态栏数据\n                    LogStatus("时间：" + _D() + "\\n" + "`" + JSON.stringify(tblPos) + "`" + "\\n" + "`" + JSON.stringify(tbl) + "`")\n                }\n            }            \n            Sleep(5000)\n        }\n        Sleep(500)\n    }\n}\n\nfunction onexit() {\n    Log("扫尾，撤销所有挂单")\n    cancelAll()\n}'

class FMZDeepPort:
    source_file = SOURCE_FILE
    source_features = SOURCE_FEATURES
    fidelity_notes = SOURCE_FIDELITY_NOTES
    javascript = ORIGINAL_JAVASCRIPT
    def run(self, adapter):
        runner = getattr(adapter, 'run_fmz_javascript', None)
        if runner is None:
            raise RuntimeError('This strategy needs an FMZ-compatible event/API adapter; refusing to invent OHLCV-only behavior.')
        return runner(self.javascript)
